class _minimalBases:
    def __init__(self, classes):
        self.classes = classes
    def __bases__(cls, seen=None):
        if seen is None:
            seen = set()
        for cls in cls.classes:
            if cls in seen:
                continue
            yield cls
            for b in cls._minimalBases(seen):
                yield b
def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    bases = _minimalBases(classes)
    return [b.__bases__ for b in bases]

