    with zipfile.ZipFile(zip_path) as zf:
        package_data = {}
        for zip_info in zf.infolist():
            if zip_info.is_dir():
                package_data[zip_info.filename] = {'files': []}
            else:
                root = ElementTree.fromstring(zf.read(zip_info.filename))
                name = root.find('Package').attrib['Name']
                package_data.setdefault(name, {})['files'].append((root, zip_info))
        for name, data in package_data.items():
            files = data['files']
            for root, zip_info in files:
                for entry in root.itersubelements('Entry'):
                    try:
                        package_data[name][entry.attrib['Path']] = entry.text
                    except KeyError:
                        pass
        return package_data

