def _fromutc(self, dt):
    """Given a timezone-aware datetime in a given timezone, calculates a
    timezone-aware datetime in a new timezone.

    Since this is the one time that we *know* we have an unambiguous datetime
    object, we take this opportunity to determine whether the datetime is
    ambiguous and in a "fold" state (e.g. if it's the first occurrence,
    chronologically, of the ambiguous datetime).

    :param dt: A timezone-aware :class:`datetime.datetime` object.
    """
    if not isinstance(dt, datetime_tz):
        if not dt.tzinfo:
            return dt.replace(tzinfo=localtz())
        dt = datetime_tz(dt)
    if not dt.tzinfo:
        return dt.astimezone(localtz())
    if dt.tzinfo.utcoffset(dt) is None:  # pragma: no cover
        # If we come across a datetime that contains no information about
        # the time offset, add the local time offset to set the time zone.
        dt = dt.replace(tzinfo=localtz())
    return dt

def normalized(self):
    """
    Return a version of this object represented entirely using integer
    values for the relative attributes.

    >>> relativedelta(days=1.5, hours=2).normalized()
    relativedelta(days=+1, hours=+14)

    :return:
        Returns a :class:`dateutil.relativedelta.relativedelta` object.
    """

    def _normalize_integer(self, value):
        if isinstance(value, float) and value.is_integer():
            return int(value)
        else:
            return value

    def _normalize_timedelta(self, value):
        value = value.total_seconds()
        if isinstance(value, float) and value.is_integer():
            return timedelta(seconds=int(value))
        else:
            return value

    return relativedelta(days=self._normalize_integer(self.days),
                         weeks=self._normalize_integer(self.weeks),
                         hours=self._normalize_integer(self.hours),
                         minutes=self._normalize_integer(self.minutes),
                         seconds=self._normalize_integer(self.seconds),
                         microseconds=self._normalize_integer(self.microseconds),
                         years=self._normalize_timedelta(self.years),
                         months=self._normalize_timedelta(self.months),
                         days=self._normalize_timedelta(self.days))

def normalized(self):
    """
    Return a version of this object represented entirely using integer
    values for the relative attributes.

    :return:
        Returns a :class:`dateutil.relativedelta.relativedelta` object.
    """
    normalized_days = round(self.days)
    if self.days != normalized_days:
        raise TypeError(f"The 'days' attribute {self.days} cannot be normalized to an integer value")
    normalized_hours = round(self.hours)
    if self.hours != normalized_hours:
        raise TypeError(f"The 'hours' attribute {self.hours} cannot be normalized to an integer value")
    normalized_minutes = round(self.minutes)
    if self.minutes != normalized_minutes:
        raise TypeError(f"The 'minutes' attribute {self.minutes} cannot be normalized to an integer value")
    normalized_seconds = round(self.seconds)
    if self.seconds != normalized_seconds:
        raise TypeError(f"The 'seconds' attribute {self.seconds} cannot be normalized to an integer value")
    normalized_microseconds = round(self.microseconds)
    if self.microseconds != normalized_microseconds:
        raise TypeError(f"The 'microseconds' attribute {self.microseconds} cannot be normalized to an integer value")
    return relativedelta(days=normalized_days, hours=normalized_hours, minutes=normalized_minutes, seconds=normalized_seconds, microseconds=normalized_microseconds)

