def get_versions():
    """
    Get version information or return default if unable to do so.
    """

    versions = {}
    try:
        import os
        import re
        import pkg_resources
        import distutils.util
        from pkg_resources import parse_version
    except ImportError:
        print("An error occurred while attempting to import necessary packages. Unable to retrieve version information.")
        return

    for root, dirs, files in os.walk(os.path.join(os.path.dirname(__file__), "..")):
        if root.endswith("build") or root.endswith("dist"):
            continue

        for file in files:
            if file.endswith(".egg-info"):
                egg_info_dir = os.path.join(root, file)
                try:
                    with open(os.path.join(egg_info_dir, "PKG-INFO"), "r") as f:
                        for line in f.readlines():
                            match = re.search(r"^Version: (.*)", line.strip())
                            if match:
                                versions[os.path.split(root)[-1]] = match.group(1)
                                break
                except OSError:  # FileNotFoundError:
                    continue

    if not versions:
        print("Unable to find any packages that provide version information.")
        return

    # formats versions dictionary
    versions = {k: parse_version(v) if v else "unknown" for k, v in versions.items()}

    # selects the highest version in each package
    versions = {k: max(v, key=lambda x: x[1]) for k, v in versions.items()}

    # formats final output
    for k, v in versions.items():
        versions[k] = distutils.util.strtobool("1" if v[1] else "0")

    return versions

