        # Check for OCFL Storage Root
        if "storage.json" in os.listdir(path):
            return "root"

        # Check for OCFL Object
        if "inventory.json" in os.listdir(path):
            return "object"

        # Check for files
        if len(os.listdir(path)) > 0:
            for file in os.listdir(path):
                if file.startswith("0="):
                    return "file"

    return "Not a valid OCFL directory structure"

