    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    # Create a list of args for each subparser
    args_for_each_subparser = {
        subparser_name: []
        for subparser_name in subparsers
    }

    # Populate each subparser's argument list with all unparsed arguments
    for unparsed_argument in unparsed_arguments:
        for subparser_name, subparser in subparsers.items():
            if subparser.add_argument(unparsed_argument):
                args_for_each_subparser[subparser_name].append(unparsed_argument)
                break

    # Parse the arguments for each subparser
    parsed_arguments_for_each_subparser = {
        subparser_name: subparser.parse_args(args_for_each_subparser[subparser_name])
        for subparser_name, subparser in subparsers.items()
    }

    # Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace
    # of arguments, a list of remaining arguments not claimed by any subparser)
    parsed_arguments = {
        subparser_name: parsed_arguments_for_each_subparser[subparser_name]
        for subparser_name in subparsers
    }
    remaining_arguments = unparsed_arguments[len(args_for_each_subparser[subparser_name]):]
    return parsed_arguments, remaining_arguments

