def size_to_bytes(size: str) -> int:
    number_pattern = re.compile(r'^[0-9]+')
    power_pattern = re.compile(r'[KMGTPEZY]')

    if not number_pattern.match(size):
        raise ValueError(f'Invalid format {size}')

    number = int(number_pattern.match(size).group(0))
    power = power_pattern.match(size).group(0)

    if power == 'K':
        return number * 1024
    elif power == 'M':
        return number * 1024 * 1024
    elif power == 'G':
        return number * 1024 * 1024 * 1024
    elif power == 'T':
        return number * 1024 * 1024 * 1024 * 1024
    elif power == 'P':
        return number * 1024 * 1024 * 1024 * 1024 * 1024
    elif power == 'E':
        return number * 1024 * 1024 * 1024 * 1024 * 1024 * 1024
    elif power == 'Z':
        return number * 1024 * 1024 * 1024 * 1024 * 1024 * 1024 * 1024
    elif power == 'Y':
        return number * 1024 * 1024 * 1024 * 1024 * 1024 * 1024 * 1024 * 1024
    else:
        raise ValueError(f'Invalid format {size}')

