        raise ValueError("alphabet and padding must be lists and integers")
    if not alphabet:
        raise ValueError("alphabet cannot be empty")
    if padding is not None and padding < 0:
        raise ValueError("padding must be a non-negative integer")

    if number == 0:
        return alphabet[0] * padding

    result = ""
    while number > 0:
        result = alphabet[number % len(alphabet)] + result
        number //= len(alphabet)

    return result.zfill(padding)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number == 0:
        return "0"

    if padding is not None:
        if number < 0:
            number = -number
            result = "-"
        else:
            result = ""
        number_str = ""
    else:
        result = ""
        number_str = ""

    remainder = number
    base = len(alphabet)
    while remainder > 0:
        number_str = alphabet[remainder % base] + number_str
        remainder //= base

    if padding is not None:
        result += ("0" * (padding - len(number_str))) + number_str
    else:
        result += number_str

