def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None
    match = re.match(r"^(\d+)\s*(\w+)$", frequency)
    if not match:
        raise ValueError("Invalid frequency: {frequency}")
    amount = int(match.group(1))
    unit = match.group(2).lower()
    if unit == "year" or unit == "yr":
        unit = "years"
    if unit == "hr" or unit == "hour" or unit == "hrs":
        unit = "hours"
    if unit == "min" or unit == "minute" or unit == "mins":
        unit = "minutes"
    if unit == "sec" or unit == "second" or unit == "secs":
        unit = "seconds"
    return datetime.timedelta(**{unit: amount})
