    """Insert a value of a nested key into a dictionary.

    To insert a value for a nested key, all ancestor keys must be provided as
    method arguments.

    Example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: A dictionary object to insert the nested key value into.
    :param val: A value to insert to the given dictionary.
    :param key: First key in a chain of keys that will store the value.
    :param keys: Subkeys in the key chain.
    """
    if len(keys) > 0:
        sub_dict = dic.get(key)
        if sub_dict is None:
            sub_dict = {}
            dic[key] = sub_dict

        key = keys[0]
        keys = keys[1:]
        return dict_insert(sub_dict, val, key, *keys)
    else:
        if key in dic:
            raise KeyError(f"Cannot insert value for key {key} as it already exist")

        dic[key] = val

